def compare_author_fields(e1_authors, e2_authors):
    for i in _author_records(e1_authors):
        for j in _author_records(e2_authors):
            i_db_name = i.get('db_name')
            j_db_name = j.get('db_name')
            if i_db_name and j_db_name and normalize(str(i_db_name)) == normalize(str(j_db_name)):
                return True

            i_name = i.get('name') or i_db_name
            j_name = j.get('name') or j_db_name
            if i_name and j_name and normalize(str(i_name)).strip('.') == normalize(str(j_name)).strip('.'):
                return True
    return False


def compare_author_keywords(e1_authors, e2_authors):
    max_score = 0
    for i in _author_records(e1_authors):
        for j in _author_records(e2_authors):
            name1 = i.get('name') or i.get('db_name') or ''
            name2 = j.get('name') or j.get('db_name') or ''
            if not name1 or not name2:
                continue
            percent, ordered = keyword_match(str(name1), str(name2))
            if percent > 0.50:
                score = percent * 80
                if ordered:
                    score += 10
                if score > max_score:
                    max_score = score
    if max_score:
        return ('authors', 'keyword match', max_score)
    else:
        return ('authors', 'mismatch', -200)


def compare_authors(e1, e2):
    """
    Compares the authors of two edition representations and
    returns a evaluation and score.

    :param dict e1: Edition, output of expand_record()
    :param dict e2: Edition, output of expand_record()
    :rtype: tuple
    :return: str?, message, score
