    e2 = expand_record(e2)
    level1 = level1_merge(e1, e2)
    total = sum(i[2] for i in level1)
    if debug:
        print(f"E1: {e1}\nE2: {e2}")
        print(f"TOTAL 1 = {total} : {level1}")
    if total >= threshold:
        return True
    level2 = level2_merge(e1, e2)
    total = sum(i[2] for i in level2)
    if debug:
        print(f"TOTAL 2 = {total} : {level2}")
    return total >= threshold


def editions_match(e1, e2, threshold=875, debug=False):
    """Compare raw or expanded edition records using the matching threshold."""
    return threshold_match(e1, e2, threshold, debug=debug)

